begin;

-- Validated task-designer/RPC bundle, adapted to has_org_permission and text task priorities.
-- Mobile-only task designer. Legacy task/report RPCs remain untouched; report_flow distinguishes new tasks.
-- The historical one-snapshot-per-task constraint was generated by PostgreSQL from "task_id uuid UNIQUE".
alter table public.task_report_form_snapshots drop constraint if exists task_report_form_snapshots_task_id_key;

create table if not exists public.task_categories (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  code text not null check (code ~ '^[a-z][a-z0-9_-]{1,47}$'),
  title text not null check (length(trim(title)) between 1 and 120),
  parent_id uuid,
  is_main boolean not null default false,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  unique (organization_id, code), unique (organization_id, id),
  foreign key (organization_id, parent_id) references public.task_categories(organization_id,id) on delete cascade,
  check (parent_id is null or not is_main)
);
create unique index if not exists task_categories_main_code_uq on public.task_categories(organization_id,code) where is_main;
insert into public.task_categories(organization_id,code,title,is_main)
select o.id,c.code,c.title,true from public.organizations o
 cross join (values ('finance','المالية'),('sales','المبيعات'),('purchases','المشتريات'),('warehouse','المستودع'),('items','الأصناف'),('admin','الإدارة'),('other','أخرى')) c(code,title)
on conflict (organization_id,code) do nothing;


create or replace function public.task_library_allowed_for_org(p_organization_id uuid, p_required_permission text default 'task_library.read')
returns boolean language sql security definer set search_path=public,auth as $$
  select auth.uid() is not null and p_required_permission in ('task_library.read','task_library.manage')
    and public.has_org_permission(p_organization_id,p_required_permission,null::uuid)
$$;
revoke all on function public.task_library_allowed_for_org(uuid,text) from public,anon;
grant execute on function public.task_library_allowed_for_org(uuid,text) to authenticated;

create or replace function public.list_task_library_report_forms(p_organization_id uuid)
returns table(id uuid, code text, title text, description text, role_code text, is_active boolean, approved_version_id uuid, approved_version_no integer)
language sql security definer set search_path=public,auth as $$
  select t.id,t.code,t.title,t.description,t.role_code,t.is_active,v.id,v.version_no
  from public.report_form_templates t
  join lateral (
    select rv.id,rv.version_no
    from public.report_form_versions rv
    where rv.template_id=t.id and rv.status='published' and rv.approved_by is not null and rv.approved_at is not null
    order by rv.version_no desc limit 1
  ) v on true
  where t.organization_id=p_organization_id and t.is_active
    and public.task_library_allowed_for_org(p_organization_id,'task_library.manage')
  order by t.title
  limit 500
$$;
revoke all on function public.list_task_library_report_forms(uuid) from public,anon;
grant execute on function public.list_task_library_report_forms(uuid) to authenticated;

alter table public.task_templates add column if not exists instructions text;
alter table public.task_templates add column if not exists category_id uuid;
alter table public.task_templates add column if not exists subcategory_id uuid;
alter table public.task_templates add column if not exists default_duration_minutes integer;
alter table public.task_templates add column if not exists version integer not null default 1;
do $$ begin
 alter table public.task_templates add constraint task_templates_category_fk foreign key(organization_id,category_id) references public.task_categories(organization_id,id);
exception when duplicate_object then null; end $$;
do $$ begin
 alter table public.task_templates add constraint task_templates_subcategory_fk foreign key(organization_id,subcategory_id) references public.task_categories(organization_id,id);
exception when duplicate_object then null; end $$;
do $$ begin
 alter table public.task_templates add constraint task_templates_duration_check check(default_duration_minutes is null or default_duration_minutes between 1 and 10080);
exception when duplicate_object then null; end $$;

create table if not exists public.task_template_steps (
 id uuid primary key default gen_random_uuid(), template_id uuid not null references public.task_templates(id) on delete cascade,
 title text not null check(length(trim(title)) between 1 and 200), instructions text, sort_order integer not null check(sort_order>=0),
 is_required boolean not null default true, evidence_required boolean not null default false, evidence_instructions text,
 unique(template_id,sort_order)
);
create table if not exists public.task_template_report_forms (
 id uuid primary key default gen_random_uuid(), template_id uuid not null references public.task_templates(id) on delete cascade,
 version_id uuid not null references public.report_form_versions(id) on delete restrict,
 sort_order integer not null check(sort_order>=0), is_required boolean not null default true,
 unique(template_id,version_id), unique(template_id,sort_order)
);
create table if not exists public.task_execution_steps (
 id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade,
 source_template_step_id uuid references public.task_template_steps(id) on delete set null,
 title text not null, instructions text, sort_order integer not null,
 is_required boolean not null default true, evidence_required boolean not null default false, evidence_instructions text,
 completed_by uuid references auth.users(id), completed_at timestamptz,
 unique(task_id,sort_order), unique(task_id,id)
);
alter table public.task_attachments add column if not exists execution_step_id uuid references public.task_execution_steps(id) on delete set null;

alter table public.task_report_form_snapshots add column if not exists title text;
alter table public.task_report_form_snapshots add column if not exists sort_order integer not null default 0;
alter table public.task_report_form_snapshots add column if not exists is_required boolean not null default true;
alter table public.task_report_form_snapshots add column if not exists organization_id uuid references public.organizations(id);
alter table public.task_report_form_snapshots add column if not exists task_report_form_id uuid references public.task_template_report_forms(id) on delete set null;
alter table public.task_reports add column if not exists organization_id uuid references public.organizations(id);


create table if not exists public.task_report_drafts (
  id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade,
  snapshot_id uuid not null references public.task_report_form_snapshots(id) on delete cascade,
  employee_id uuid not null references auth.users(id) on delete cascade,
  values jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now(),
  unique(task_id,snapshot_id,employee_id)
);

alter table public.tasks add column if not exists starts_at timestamptz;
alter table public.tasks add column if not exists task_instructions text;
alter table public.tasks add column if not exists category_id uuid;
alter table public.tasks add column if not exists subcategory_id uuid;
alter table public.tasks add column if not exists report_flow text not null default 'legacy';
alter table public.tasks add column if not exists proof_required boolean not null default false;
alter table public.tasks add column if not exists proof_instructions text;
alter table public.tasks add column if not exists template_version integer;
do $$ begin
 alter table public.tasks add constraint tasks_category_fk foreign key(organization_id,category_id) references public.task_categories(organization_id,id);
exception when duplicate_object then null; end $$;
do $$ begin
 alter table public.tasks add constraint tasks_subcategory_fk foreign key(organization_id,subcategory_id) references public.task_categories(organization_id,id);
exception when duplicate_object then null; end $$;
alter table public.tasks drop constraint if exists tasks_report_flow_check;
alter table public.tasks add constraint tasks_report_flow_check check(report_flow in ('legacy','multi_form'));

create index if not exists task_execution_steps_task_order_idx on public.task_execution_steps(task_id,sort_order);
create index if not exists task_template_report_forms_order_idx on public.task_template_report_forms(template_id,sort_order);
create index if not exists task_report_form_snapshots_task_order_idx on public.task_report_form_snapshots(task_id,sort_order);
create unique index if not exists task_report_form_snapshots_task_template_uq on public.task_report_form_snapshots(task_id,template_id) where template_id is not null;

alter table public.task_categories enable row level security;
alter table public.task_template_steps enable row level security;
alter table public.task_template_report_forms enable row level security;
alter table public.task_execution_steps enable row level security;
drop policy if exists task_categories_read on public.task_categories;
drop policy if exists task_categories_manage on public.task_categories;
drop policy if exists task_template_steps_read on public.task_template_steps;
drop policy if exists task_template_steps_manage on public.task_template_steps;
drop policy if exists task_template_report_forms_read on public.task_template_report_forms;
drop policy if exists task_template_report_forms_manage on public.task_template_report_forms;
drop policy if exists task_execution_steps_read on public.task_execution_steps;
drop policy if exists task_execution_steps_update on public.task_execution_steps;
create policy task_categories_read on public.task_categories for select to authenticated using(public.has_org_permission(organization_id,'task_library.read',null::uuid));
create policy task_categories_manage on public.task_categories for all to authenticated using(public.has_org_permission(organization_id,'task_library.manage',null::uuid)) with check(public.has_org_permission(organization_id,'task_library.manage',null::uuid));
create policy task_template_steps_read on public.task_template_steps for select to authenticated using(exists(select 1 from public.task_templates t where t.id=template_id and public.has_org_permission(t.organization_id,'task_library.read',null::uuid)));
create policy task_template_steps_manage on public.task_template_steps for all to authenticated using(exists(select 1 from public.task_templates t where t.id=template_id and public.has_org_permission(t.organization_id,'task_library.manage',null::uuid))) with check(exists(select 1 from public.task_templates t where t.id=template_id and public.has_org_permission(t.organization_id,'task_library.manage',null::uuid)));
create policy task_template_report_forms_read on public.task_template_report_forms for select to authenticated using(exists(select 1 from public.task_templates t where t.id=template_id and public.has_org_permission(t.organization_id,'task_library.read',null::uuid)));
create policy task_template_report_forms_manage on public.task_template_report_forms for all to authenticated using(exists(select 1 from public.task_templates t where t.id=template_id and public.has_org_permission(t.organization_id,'task_library.manage',null::uuid))) with check(exists(select 1 from public.task_templates t where t.id=template_id and public.has_org_permission(t.organization_id,'task_library.manage',null::uuid)));
create policy task_execution_steps_read on public.task_execution_steps for select to authenticated using(exists(select 1 from public.tasks t where t.id=task_id and (t.assigned_to=auth.uid() or t.created_by=auth.uid() or public.has_org_permission(t.organization_id,'tasks.manage',null::uuid) or public.has_org_permission(t.organization_id,'tasks.review',null::uuid))));
revoke insert,update,delete on public.task_execution_steps from authenticated;
grant select on public.task_execution_steps to authenticated;
grant select,insert,update,delete on public.task_categories to authenticated;
grant select on public.task_template_steps,public.task_template_report_forms to authenticated;

create policy task_report_drafts_select on public.task_report_drafts for select to authenticated using (
  employee_id=auth.uid() or exists(select 1 from public.tasks t where t.id=task_id and public.has_org_permission(t.organization_id,'tasks.review',null::uuid))
);
create policy task_report_drafts_insert on public.task_report_drafts for insert to authenticated with check (
  employee_id=auth.uid() and exists(select 1 from public.tasks t where t.id=task_id and t.assigned_to=auth.uid() and t.report_flow='multi_form')
);
create policy task_report_drafts_update on public.task_report_drafts for update to authenticated using(employee_id=auth.uid()) with check(employee_id=auth.uid());
grant select,insert,update on public.task_report_drafts to authenticated;

create or replace function public.save_task_designer_template(p_organization_id uuid,p_template_id uuid,p_payload jsonb)
returns uuid language plpgsql security definer set search_path=public,auth as $$
declare v_id uuid:=coalesce(p_template_id,gen_random_uuid()); v_role text; v_form jsonb; v_step jsonb; v_version uuid;
begin
 if auth.uid() is null or not public.has_org_permission(p_organization_id,'task_library.manage',null::uuid) then raise exception using errcode='42501',message='permission_denied'; end if;
 if jsonb_typeof(p_payload)<>'object' or jsonb_typeof(coalesce(p_payload->'steps','[]'))<>'array' or jsonb_typeof(coalesce(p_payload->'report_forms','[]'))<>'array' then raise exception using errcode='22023',message='invalid_template_payload'; end if;
 v_role:=p_payload->>'role_code';
 if not exists(select 1 from public.roles where institution_id=p_organization_id and code=v_role) then raise exception using errcode='22023',message='invalid_task_role'; end if;
 if p_payload->>'category_id' is not null and not exists(select 1 from public.task_categories c where c.id=(p_payload->>'category_id')::uuid and c.organization_id=p_organization_id and c.parent_id is null) then raise exception using errcode='22023',message='invalid_task_category'; end if;
 if p_payload->>'subcategory_id' is not null and not exists(select 1 from public.task_categories c join public.task_categories p on p.id=c.parent_id where c.id=(p_payload->>'subcategory_id')::uuid and c.organization_id=p_organization_id and p.id=(p_payload->>'category_id')::uuid) then raise exception using errcode='22023',message='invalid_task_subcategory'; end if;
 insert into public.task_templates(id,organization_id,code,title,description,role_code,task_type,default_priority,category_id,subcategory_id,instructions,default_duration_minutes,is_active)
 values(v_id,p_organization_id,'td_'||substr(replace(v_id::text,'-',''),1,20),trim(p_payload->>'title'),nullif(p_payload->>'description',''),v_role,coalesce(nullif(p_payload->>'task_type',''), 'operational'),coalesce(nullif(p_payload->>'default_priority',''),'normal'),nullif(p_payload->>'category_id','')::uuid,nullif(p_payload->>'subcategory_id','')::uuid,p_payload->>'instructions',nullif(p_payload->>'default_duration_minutes','')::integer,coalesce((p_payload->>'is_active')::boolean,true))
 on conflict(id) do update set title=excluded.title,description=excluded.description,role_code=excluded.role_code,task_type=excluded.task_type,default_priority=excluded.default_priority,category_id=excluded.category_id,subcategory_id=excluded.subcategory_id,instructions=excluded.instructions,default_duration_minutes=excluded.default_duration_minutes,is_active=excluded.is_active,version=public.task_templates.version+1,updated_at=now()
 where public.task_templates.organization_id=p_organization_id;
 if not found then raise exception using errcode='22023',message='task_template_not_found'; end if;
 delete from public.task_template_steps where template_id=v_id;
 for v_step in select value from jsonb_array_elements(coalesce(p_payload->'steps','[]')) loop
  insert into public.task_template_steps(template_id,title,instructions,sort_order,is_required,evidence_required,evidence_instructions) values(v_id,trim(v_step->>'title'),v_step->>'instructions',coalesce((v_step->>'sort_order')::int,0),coalesce((v_step->>'is_required')::boolean,true),coalesce((v_step->>'evidence_required')::boolean,false),v_step->>'evidence_instructions');
 end loop;
 delete from public.task_template_report_forms where template_id=v_id;
 for v_form in select value from jsonb_array_elements(coalesce(p_payload->'report_forms','[]')) loop
  v_version:=(v_form->>'version_id')::uuid;
  if not exists(select 1 from public.report_form_versions v join public.report_form_templates r on r.id=v.template_id where v.id=v_version and r.organization_id=p_organization_id and r.role_code=v_role and v.status='published' and v.approved_by is not null and v.approved_at is not null) then raise exception using errcode='22023',message='report_form_version_requires_approval_or_role_mismatch'; end if;
  insert into public.task_template_report_forms(template_id,version_id,sort_order,is_required) values(v_id,v_version,coalesce((v_form->>'sort_order')::int,0),coalesce((v_form->>'required')::boolean,true));
 end loop;
 return v_id;
end $$;

create or replace function public.assign_task_from_template(p_organization_id uuid,p_template_id uuid,p_assigned_to uuid,p_branch_id uuid,p_starts_at timestamptz,p_due_at timestamptz,p_priority text default null,p_instructions text default null,p_report_overrides jsonb default '[]'::jsonb)
returns uuid language plpgsql security definer set search_path=public,auth as $$
declare v_user uuid:=auth.uid(); v_t public.task_templates%rowtype; v_task uuid; v_form record; v_snap uuid; v_schema jsonb; v_required boolean; v_override jsonb;
begin
 if v_user is null or not public.has_org_permission(p_organization_id,'tasks.manage',null::uuid) then raise exception using errcode='42501',message='permission_denied'; end if;
 select * into v_t from public.task_templates where id=p_template_id and organization_id=p_organization_id and is_active;
 if not found then raise exception using errcode='22023',message='task_template_not_found'; end if;
 if p_starts_at is null or p_due_at is null or p_due_at<p_starts_at then raise exception using errcode='22023',message='invalid_task_schedule'; end if;
 if p_priority is not null and p_priority not in ('normal','important','urgent','critical') then raise exception using errcode='22023',message='invalid_task_priority'; end if;
 if p_report_overrides is null or jsonb_typeof(p_report_overrides)<>'array' then raise exception using errcode='22023',message='invalid_report_overrides'; end if;
 if not exists(select 1 from public.organization_memberships m join public.role_assignments r on r.organization_id=m.organization_id and r.membership_id=m.id where m.organization_id=p_organization_id and m.user_id=p_assigned_to and m.is_active and r.role_code=v_t.role_code and (p_branch_id is null or r.branch_id=p_branch_id)) then raise exception using errcode='22023',message='no_employee_for_role_branch'; end if;
 if p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id and is_active) then raise exception using errcode='22023',message='invalid_task_branch'; end if;
 insert into public.tasks(organization_id,branch_id,title,description,expected_result,assigned_to,created_by,due_at,starts_at,priority,template_id,position_code,report_flow,task_instructions,category_id,subcategory_id,proof_required,proof_instructions,template_version,report_required)
 values(p_organization_id,p_branch_id,v_t.title,v_t.description,v_t.expected_result,p_assigned_to,v_user,p_due_at,p_starts_at,coalesce(nullif(p_priority,''),v_t.default_priority)::text,p_template_id,v_t.role_code,'multi_form',coalesce(nullif(trim(p_instructions),''),v_t.instructions),v_t.category_id,v_t.subcategory_id,false,null,v_t.version,exists(select 1 from public.task_template_report_forms where template_id=v_t.id and is_required)) returning id into v_task;
 insert into public.task_execution_steps(task_id,source_template_step_id,title,instructions,sort_order,is_required,evidence_required,evidence_instructions)
 select v_task,s.id,s.title,s.instructions,s.sort_order,s.is_required,s.evidence_required,s.evidence_instructions from public.task_template_steps s where s.template_id=v_t.id order by s.sort_order;
 for v_form in select l.*,r.title from public.task_template_report_forms l join public.report_form_versions v on v.id=l.version_id join public.report_form_templates r on r.id=v.template_id where l.template_id=v_t.id order by l.sort_order loop
  v_required:=v_form.is_required;
  select value into v_override from jsonb_array_elements(p_report_overrides) value where value->>'approvedVersionId'=v_form.version_id::text limit 1;
  if v_override is not null then v_required:=coalesce((v_override->>'required')::boolean,v_required); end if;
  if v_form.is_required and not v_required then raise exception using errcode='22023',message='required_report_cannot_be_optional'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('key',f.field_key,'label',f.label,'type',f.field_type,'required',f.is_required,'repeatable',f.repeatable,'validation',f.validation,'options',f.options,'config',f.config) order by f.sort_order),'[]'::jsonb) into v_schema from public.report_form_version_fields f where f.version_id=v_form.version_id;
  insert into public.task_report_form_snapshots(task_id,template_id,version_id,report_required,schema,published_by,title,sort_order,is_required,organization_id,task_report_form_id)
  values(v_task,(select template_id from public.report_form_versions where id=v_form.version_id),v_form.version_id,v_required,v_schema,v_user,v_form.title,v_form.sort_order,v_required,p_organization_id,v_form.id) returning id into v_snap;
 end loop;
 insert into public.task_activity_log(task_id,actor_id,action,details) values(v_task,v_user,'task_assigned',jsonb_build_object('template_id',v_t.id,'template_version',v_t.version,'report_flow','multi_form'));
 return v_task;
end $$;

create or replace function public.mobile_complete_task_step(p_step_id uuid,p_evidence_attachment_ids uuid[] default '{}') returns uuid language plpgsql security definer set search_path=public,auth as $$
declare v_task public.tasks%rowtype; v_step public.task_execution_steps%rowtype;
begin
 select t.* into v_task from public.tasks t join public.task_execution_steps s on s.task_id=t.id where s.id=p_step_id for update of t;
 if not found or v_task.assigned_to<>auth.uid() then raise exception using errcode='42501',message='task_step_not_assigned'; end if;
 select * into v_step from public.task_execution_steps where id=p_step_id for update;
	 if v_task.status not in ('in_progress','needs_revision') then raise exception using errcode='22023',message='task_must_be_in_progress'; end if;
	 if v_step.evidence_required and (coalesce(array_length(p_evidence_attachment_ids,1),0)=0 or exists(select 1 from unnest(p_evidence_attachment_ids) x where not exists(select 1 from public.task_attachments a where a.id=x and a.task_id=v_task.id and a.uploaded_by=auth.uid() and (a.execution_step_id is null or a.execution_step_id=p_step_id)))) then raise exception using errcode='22023',message='task_step_evidence_required'; end if;
	 update public.task_attachments set execution_step_id=p_step_id where id=any(coalesce(p_evidence_attachment_ids,'{}')) and task_id=v_task.id and uploaded_by=auth.uid() and (execution_step_id is null or execution_step_id=p_step_id);
 update public.task_execution_steps set completed_by=auth.uid(),completed_at=now() where id=p_step_id;
 insert into public.task_activity_log(task_id,actor_id,action,details) values(v_task.id,auth.uid(),'task_step_completed',jsonb_build_object('step_id',p_step_id));
 return p_step_id;
end $$;

create or replace function public.save_task_report_draft(p_task_id uuid,p_snapshot_id uuid,p_values jsonb)
returns uuid language plpgsql security definer set search_path=public,auth as $$
declare v_id uuid;
begin
 if auth.uid() is null or p_values is null or jsonb_typeof(p_values)<>'object' then raise exception using errcode='22023',message='invalid_task_report_draft'; end if;
 if not exists(select 1 from public.tasks t join public.task_report_form_snapshots s on s.task_id=t.id and s.id=p_snapshot_id where t.id=p_task_id and t.assigned_to=auth.uid() and t.report_flow='multi_form') then raise exception using errcode='42501',message='task_draft_not_allowed'; end if;
 insert into public.task_report_drafts(task_id,snapshot_id,employee_id,values,updated_at) values(p_task_id,p_snapshot_id,auth.uid(),p_values,now())
 on conflict(task_id,snapshot_id,employee_id) do update set values=excluded.values,updated_at=now() returning id into v_id;
 return v_id;
end $$;

create or replace function public.mobile_submit_task_report_form(p_task_id uuid,p_snapshot_id uuid,p_values jsonb,p_idempotency_key text default null) returns jsonb language plpgsql security definer set search_path=public,auth as $$
declare v_task public.tasks%rowtype; v_snapshot public.task_report_form_snapshots%rowtype; v_report public.task_reports%rowtype; v_field jsonb; v_raw jsonb; v_key text; v_type text; v_clean jsonb:=p_values; v_sigs jsonb:='[]'; v_sig jsonb; v_sig_id uuid; v_now timestamptz:=now(); v_idem text;
begin
 if auth.uid() is null then raise exception using errcode='28000',message='not_authenticated'; end if;
	 if p_values is null or jsonb_typeof(p_values)<>'object' then raise exception using errcode='22023',message='invalid_task_report_payload'; end if;
	 if p_idempotency_key is not null and (length(trim(p_idempotency_key))=0 or length(p_idempotency_key)>200) then raise exception using errcode='22023',message='invalid_report_idempotency_key'; end if;
 v_idem:=coalesce(nullif(trim(p_idempotency_key),''),'report:'||p_task_id||':'||p_snapshot_id||':'||gen_random_uuid());
 select * into v_task from public.tasks where id=p_task_id and deleted_at is null for update;
 if not found or v_task.assigned_to<>auth.uid() or v_task.report_flow<>'multi_form' then raise exception using errcode='P0002',message='task_not_found'; end if;
 if not exists(select 1 from public.organization_memberships m where m.organization_id=v_task.organization_id and m.user_id=auth.uid() and m.is_active) then raise exception using errcode='42501',message='employee_not_active'; end if;
 select * into v_report from public.task_reports where submitted_by=auth.uid() and idempotency_key=v_idem;
 if found then if v_report.task_id<>p_task_id or v_report.report_form_snapshot_id<>p_snapshot_id then raise exception using errcode='22023',message='report_idempotency_key_conflict'; end if; return jsonb_build_object('report_id',v_report.id,'task_id',v_report.task_id,'snapshot_id',v_report.report_form_snapshot_id,'values',v_report.values); end if;
 if v_task.status not in ('in_progress','needs_revision','report_submitted') then raise exception using errcode='22023',message='task_must_be_in_progress'; end if;
 if exists(select 1 from public.task_execution_steps s where s.task_id=p_task_id and s.is_required and s.completed_at is null) then raise exception using errcode='22023',message='required_task_steps_incomplete'; end if;
 if v_task.proof_required and not exists(select 1 from public.task_attachments a where a.task_id=p_task_id and a.execution_step_id is null) then raise exception using errcode='22023',message='task_proof_required'; end if;
	 select * into v_snapshot from public.task_report_form_snapshots where id=p_snapshot_id and task_id=p_task_id;
	 if not found then raise exception using errcode='22023',message='task_report_snapshot_missing'; end if;
	 if exists(select 1 from public.task_reports where task_id=p_task_id and report_form_snapshot_id=p_snapshot_id and status in ('submitted','approved')) then raise exception using errcode='22023',message='report_form_already_submitted'; end if;
 for v_key in select jsonb_object_keys(p_values) loop if not exists(select 1 from jsonb_array_elements(v_snapshot.schema) f(value) where f.value->>'key'=v_key) then raise exception using errcode='22023',message='unknown_report_field:'||v_key; end if; end loop;
 for v_field in select value from jsonb_array_elements(v_snapshot.schema) loop
  v_key:=coalesce(v_field->>'key',''); v_raw:=p_values->v_key; v_type:=coalesce(v_field->>'type','');
  perform public.report_validate_field(v_field,v_raw,p_values,p_task_id);
  if v_type='signature' and jsonb_typeof(v_raw)='object' and jsonb_typeof(v_raw->'strokes')='array' and jsonb_array_length(v_raw->'strokes')>0 then
   v_sig_id:=gen_random_uuid(); v_clean:=jsonb_set(v_clean,array[v_key],jsonb_build_object('signature_attachment_id',v_sig_id,'acknowledged',coalesce(v_raw->'acknowledged','false'::jsonb),'signed_at',v_now),true);
   v_sigs:=v_sigs||jsonb_build_array(jsonb_build_object('id',v_sig_id,'field_key',v_key,'strokes',v_raw->'strokes','consent_text',coalesce(v_field->'config'->>'consent_text',''),'acknowledged',coalesce((v_raw->>'acknowledged')::boolean,false)));
  elsif v_type='signature' then v_clean:=v_clean-v_key; end if;
 end loop;
 insert into public.task_reports(task_id,submitted_by,status,values,submitted_at,report_form_snapshot_id,idempotency_key,organization_id)
 values(p_task_id,auth.uid(),'submitted',v_clean,v_now,p_snapshot_id,v_idem,v_task.organization_id) returning * into v_report;
 for v_sig in select value from jsonb_array_elements(v_sigs) loop
  insert into public.task_report_signature_attachments(id,task_id,report_id,report_form_snapshot_id,field_key,signed_by,consent_text,acknowledged,stroke_paths,signed_at)
  values((v_sig->>'id')::uuid,p_task_id,v_report.id,p_snapshot_id,v_sig->>'field_key',auth.uid(),v_sig->>'consent_text',(v_sig->>'acknowledged')::boolean,v_sig->'strokes',v_now);
 end loop;
 insert into public.task_activity_log(task_id,actor_id,action,details) values(p_task_id,auth.uid(),'report_submitted',jsonb_build_object('report_id',v_report.id,'snapshot_id',p_snapshot_id));
 if not exists(select 1 from public.task_report_form_snapshots s where s.task_id=p_task_id and s.is_required and not exists(select 1 from public.task_reports r where r.task_id=p_task_id and r.report_form_snapshot_id=s.id and r.status in ('submitted','approved'))) then update public.tasks set status='report_submitted',report_submitted_at=v_now,updated_at=v_now where id=p_task_id; end if;
 return jsonb_build_object('report_id',v_report.id,'task_id',p_task_id,'snapshot_id',p_snapshot_id,'values',v_clean);
end $$;

create or replace function public.mobile_review_task_form_report(p_report_id uuid,p_decision text,p_note text default null) returns jsonb language plpgsql security definer set search_path=public,auth as $$
declare v_report public.task_reports%rowtype; v_task public.tasks%rowtype; v_next text;
begin
 select * into v_report from public.task_reports where id=p_report_id for update;
 if not found then raise exception using errcode='P0002',message='report_not_found'; end if;
 select * into v_task from public.tasks where id=v_report.task_id for update;
 if v_task.report_flow<>'multi_form' or not public.has_org_permission(v_task.organization_id,'tasks.review',null::uuid) or v_task.assigned_to=auth.uid() then raise exception using errcode='42501',message='review_not_allowed'; end if;
 if p_decision not in ('approved','returned') or v_report.status<>'submitted' then raise exception using errcode='22023',message='invalid_report_review'; end if;
	 update public.task_reports set status=p_decision,reviewed_by=auth.uid(),reviewed_at=now(),review_action=case when p_decision='approved' then 'approved'::text else 'returned_for_revision'::text end,review_note=nullif(trim(p_note),'') where id=p_report_id returning * into v_report;
 insert into public.task_activity_log(task_id,actor_id,action,details) values(v_task.id,auth.uid(),'report_'||p_decision,jsonb_build_object('report_id',p_report_id,'snapshot_id',v_report.report_form_snapshot_id,'note',p_note));
 if p_decision='returned' then update public.tasks set status='needs_revision',updated_at=now() where id=v_task.id;
	 elsif not exists(select 1 from public.task_report_form_snapshots s where s.task_id=v_task.id and s.is_required and not exists(select 1 from public.task_reports r where r.task_id=v_task.id and r.report_form_snapshot_id=s.id and r.status='approved')) and not exists(select 1 from public.task_reports r join public.task_report_form_snapshots s on s.id=r.report_form_snapshot_id where r.task_id=v_task.id and not s.is_required and r.status='submitted') then update public.tasks set status='completed_approved',approved_at=now(),updated_at=now() where id=v_task.id; end if;
 return jsonb_build_object('report_id',v_report.id,'status',v_report.status,'task_id',v_task.id);
end $$;

revoke all on function public.save_task_designer_template(uuid,uuid,jsonb) from public,anon,authenticated;
revoke all on function public.assign_task_from_template(uuid,uuid,uuid,uuid,timestamptz,timestamptz,text,text,jsonb) from public,anon,authenticated;
revoke all on function public.mobile_complete_task_step(uuid,uuid[]) from public,anon,authenticated;
revoke all on function public.mobile_submit_task_report_form(uuid,uuid,jsonb,text) from public,anon,authenticated;
revoke all on function public.save_task_report_draft(uuid,uuid,jsonb) from public,anon,authenticated;
revoke all on function public.mobile_review_task_form_report(uuid,text,text) from public,anon,authenticated;
grant execute on function public.save_task_designer_template(uuid,uuid,jsonb) to authenticated;
grant execute on function public.assign_task_from_template(uuid,uuid,uuid,uuid,timestamptz,timestamptz,text,text,jsonb) to authenticated;
grant execute on function public.mobile_complete_task_step(uuid,uuid[]) to authenticated;
grant execute on function public.mobile_submit_task_report_form(uuid,uuid,jsonb,text) to authenticated;
grant execute on function public.save_task_report_draft(uuid,uuid,jsonb) to authenticated;
grant execute on function public.mobile_review_task_form_report(uuid,text,text) to authenticated;

-- Defense in depth: any path that moves a new multi-form task to review/completion must respect its required steps and reports.
create or replace function public.guard_multi_form_task_completion()
returns trigger language plpgsql security definer set search_path=public,auth as $$
begin
 if new.report_flow='multi_form' and new.status is distinct from old.status then
  if new.status in ('report_submitted','completed_approved') and exists(select 1 from public.task_execution_steps s where s.task_id=new.id and s.is_required and s.completed_at is null) then
   raise exception using errcode='22023',message='required_task_steps_incomplete';
  end if;
  if new.status='report_submitted' and exists(select 1 from public.task_report_form_snapshots s where s.task_id=new.id and s.is_required and not exists(select 1 from public.task_reports r where r.task_id=new.id and r.report_form_snapshot_id=s.id and r.status in ('submitted','approved'))) then
   raise exception using errcode='22023',message='required_task_reports_incomplete';
  end if;
  if new.status='completed_approved' and (exists(select 1 from public.task_report_form_snapshots s where s.task_id=new.id and s.is_required and not exists(select 1 from public.task_reports r where r.task_id=new.id and r.report_form_snapshot_id=s.id and r.status='approved')) or exists(select 1 from public.task_reports r where r.task_id=new.id and r.status='submitted')) then
   raise exception using errcode='22023',message='required_task_reports_not_approved';
  end if;
 end if;
 return new;
end $$;
drop trigger if exists guard_multi_form_task_completion on public.tasks;
create trigger guard_multi_form_task_completion before update of status on public.tasks for each row execute function public.guard_multi_form_task_completion();

commit;
